function polyselfFormWithDiet() {
    const form = polyselfForm();
    if (!form) return null;
    const name = String(form.name || '').toLowerCase();
    const overlay = POLYSELF_DIET_OVERLAY.get(name);
    if (!overlay) return form;
    const result = { ...overlay, ...form };
    if (!Object.prototype.hasOwnProperty.call(result, 'carnivorous')
        && Object.prototype.hasOwnProperty.call(form, 'carnivore'))
        result.carnivorous = form.carnivore;
    return result;
}

function polyselfNoHands() {
    return !!polyselfForm()?.nohands;
}

function adjustedMonsterResumeIndexForRemoval(mon, resumeIndex) {
    if (!resumeIndex || !mon || !game.level?.monsters) return resumeIndex;
    const reverseIndex = [...game.level.monsters].reverse().indexOf(mon);
    if (reverseIndex >= 0 && reverseIndex < resumeIndex)
        return resumeIndex - 1;
    return resumeIndex;
}

function monsterHasOlfaction(data = {}) {
    const name = String(data.name || '').toLowerCase();
    const mlet = data.mlet ?? data.glyph ?? '';
    if (name.endsWith(' golem')) return false;
    if (['e', 'j', 'P', 'b', 'v', 'E', 'F', 'y'].includes(mlet)) return false;
    if (['eye', 'jelly', 'pudding', 'blob', 'vortex', 'elemental', 'fungus', 'light'].includes(mlet)) return false;
    if (/sphere$/.test(name)) return false;
    return true;
}

function scareNearbyOlfactoryMonstersWithGarlic() {
    const form = polyselfForm();
    if (form?.undead) return;
    const ux = game.u?.ux ?? 0;
    const uy = game.u?.uy ?? 0;
    for (const mon of game.level?.monsters || []) {
        const dx = (mon.mx ?? 0) - ux;
        const dy = (mon.my ?? 0) - uy;
        if (dx * dx + dy * dy >= 7 || !monsterHasOlfaction(mon.data)) continue;
        mon.mflee = 1;
        mon.mfleetim = 0;
        clearMonsterTrack(mon);
    }
}

function isWandItem(item) {
    return item?.cls === 'wand' || item?.glyph === '/' || item?.wandIndex != null
        || item?.kind === 'wand of sleep' || item?.kind === 'sleep';
}
const WISHING_WAND_INDEX = 4;
const WAND_WREST_CHANCE = 121;

function isWishingWand(item) {
    const wand = String(item?.wand || '').toLowerCase();
    const kind = String(item?.kind || '').toLowerCase();
    const actualKind = String(item?.actualKind || '').toLowerCase();
    return item?.wandIndex === WISHING_WAND_INDEX
        || wand === 'wishing'
        || kind === 'wishing'
        || kind === 'wand of wishing'
        || actualKind === 'wishing'
        || actualKind === 'wand of wishing';
}

function wandCharges(item, fallback = 0) {
    return item?.spe ?? item?.charges ?? fallback;
}

function setWandCharges(item, charges) {
    item.spe = charges;
    item.charges = charges;
}

function refreshWandLine(item) {
    if (/\(\d+:-?\d+\)/.test(String(item.line || ''))) item.chargeKnown = true;
    item.line = normalInventoryLine({ ...item, line: '' });
}

function setKnownWandLine(item, wand) {
    item.cls = 'wand';
    item.glyph = '/';
    item.wand = wand;
    item.kind = wand;
    item.wandIndex = WAND_NAME_TO_INDEX.get(wand);
    item.known = true;
    refreshWandLine(item);
}

function zappableWand(item, { fallbackCharges = 0 } = {}) {
    const charges = wandCharges(item, fallbackCharges);
    if (charges < 0) return { zapped: false, dust: true };
    if (charges === 0) {
        if (rn2(WAND_WREST_CHANCE)) return { zapped: false };
        setWandCharges(item, -1);
        return { zapped: true, wrested: true };
    }
    setWandCharges(item, charges - 1);
    return { zapped: true };
}

function spendZapWandCharge(item, messages) {
    const charges = wandCharges(item, 8);
    checkUnpaidUsage(item, messages, { chargeCount: charges });
    return zappableWand(item, { fallbackCharges: 8 });
}

function spendEngraveWandCharge(item, messages) {
    const chargeUse = zappableWand(item);
    if (!chargeUse.zapped) return chargeUse;
    checkUnpaidUsage(item, messages, { chargeCount: wandCharges(item) });
    refreshWandLine(item);
    return chargeUse;
}

function spendChargedToolUse(item, messages) {
    const charges = chargedUsageChargeCount(item);
    if (charges <= 0) return false;
    checkUnpaidUsage(item, messages, { chargeCount: charges });
    item.spe = Math.max(0, charges - 1);
    if ('charges' in item) item.charges = item.spe;
    updateChargedItemLine(item);
    return true;
}

function heroHasSlipperyFingers() {
    return !!(game.u?._glibTimeout || game.u?.glib || (game.u?._statusSuffix || '').includes('Slippery'));
}

function heroIsFumbling() {
    return !!(game.u?.fumbling || game.u?._fumblingTimeout || (game.u?._statusSuffix || '').includes('Fumbling')
        || (game.inventory || []).some(item => isWornArmorItem(item)
            && String(item.kind || item.actualKind || '').toLowerCase() === 'fumble boots'));
}

function fingersOrGloves() {
    return wornGlovesItem() ? 'gloves' : 'fingers';
}

function wornRingItem(item) {
    return !!item && (item.cls === 'ring' || item.glyph === '=' || item.otyp === RING_CLASS)
        && (item.worn || /\(on (?:left|right) hand\)/.test(String(item.line || '')));
}

function wornArmorInSlot(slot) {
    return (game.inventory || []).find(item => isWornArmorItem(item) && armorSlot(item) === slot) || null;
}

function greaseInaccessibleBlockers(item) {
    if (!item) return [];
    if (isWornArmorItem(item)) {
        const slot = armorSlot(item);
        if (slot === 'body') {
            const cloak = wornArmorInSlot('cloak');
            return cloak && cloak !== item ? [cloak] : [];
        }
        if (slot === 'shirt') {
            return [wornArmorInSlot('cloak'), wornArmorInSlot('body')]
                .filter(blocker => blocker && blocker !== item);
        }
    }
    if (wornRingItem(item)) {
        const gloves = wornGlovesItem();
        return gloves ? [gloves] : [];
    }
    return [];
}

function ownedEquipmentName(item) {
    return `your ${inventoryItemName(item).replace(/^(?:an?|the) /i, '')}`;
}

function ownedEquipmentListName(items) {
    const names = items.map(item => inventoryItemName(item).replace(/^(?:an?|the) /i, ''));
    return `your ${names.join(' and ')}`;
}

function canGreaseObject(item) {
    return !!item && item.cls !== 'coin' && item.letter !== '$'
        && !greaseInaccessibleBlockers(item).length;
}

function canSelectGreaseObject(item) {
    return !!item && item.cls !== 'coin' && item.letter !== '$';
}

function isSqueakyBoardGreaseTool(item) {
    return !!item && item.cls === 'tool' && toolChargeKind(item) === 'can of grease';
}

function isKnownSqueakyBoardOil(item) {
    if (!isPotionOfOil(item)) return false;
    const kind = objectKindKey(item).replace(/^potion of /, '');
    return item.known === true || kind === 'oil'
        || (game._discoveries || []).some(entry =>
            entry.section === 'Potions' && entry.name === 'potion of oil' && entry.known !== false);
}

function isSqueakyBoardSuggestedUntrapTool(item) {
    return isSqueakyBoardGreaseTool(item) || isKnownSqueakyBoardOil(item);
}

function isSqueakyBoardUntrapTool(item) {
    return isSqueakyBoardSuggestedUntrapTool(item) || isPotionObject(item);
}

function isBadSqueakyBoardUntrapTool(item) {
    if (!item || item.cursed) return true;
    if (isPotionOfOil(item)) return !!(item.lamplit || item.burning);
    if (isSqueakyBoardGreaseTool(item)) return (item.spe ?? 0) <= 0;
    return true;
}

function useSqueakyBoardUntrapTool(item, messages) {
    if (isSqueakyBoardGreaseTool(item))
        return spendChargedToolUse(item, messages);
    if (isPotionOfOil(item)) {
        useUpInventoryItem(item, 1);
        identifyPotionOfOil(item);
        return true;
    }
    return false;
}

function squeakyBoardUntrapChance(trap) {
    let chance = 3;
    if (heroIsConfused() || heroIsHallucinating()) chance++;
    if (game.u?.blind || game.u?.Blind) chance++;
    if (heroIsStunned()) chance += 2;
    if (heroIsFumbling()) chance *= 2;
    if (trap?.madeby_u) chance--;
    return Math.max(1, chance);
}

function squeakyBoardUntrapPrompt() {
    const letters = inventoryLetters(isSqueakyBoardSuggestedUntrapTool);
    return letters
        ? `What do you want to untrap with? [${getobjPromptLetters(letters)} or ?*]`
        : 'What do you want to untrap with? [*]';
}

function greaseTargetPrompt() {
    const letters = inventoryLetters(canGreaseObject);
    const display = letters ? `- ${getobjPromptLetters(letters)}` : '-';
    return `What do you want to grease? [${display} or ?*]`;
}

function greaseInaccessibleMessage(item) {
    const blockers = greaseInaccessibleBlockers(item);
    if (!blockers.length) return '';
    return `You need to take off ${ownedEquipmentListName(blockers)} to grease ${ownedEquipmentName(item)}.`;
}

function addHeroGlibTimeout(duration) {
    if (!game.u) return;
    game.u._glibTimeout = (game.u._glibTimeout || 0) + duration;
}

function dropCarriedObjectAtHero(item, messages = []) {
    const dropped = {
        ...item,
        invlet: item.invlet ?? item.letter,
        letter: undefined,
        line: undefined,
        wielded: false,
        worn: false,
        quivered: false,
        ox: game.u?.ux || 0,
        oy: game.u?.uy || 0,
        glyph: item.glyph || (item.cls === 'weapon' ? ')' : item.cls === 'armor' ? '[' : item.cls === 'wand' ? '/'
            : item.cls === 'ring' ? '=' : item.cls === 'potion' ? '!' : item.cls === 'scroll' ? '?'
                : item.cls === 'spellbook' ? '+' : '('),
        color: item.color ?? (item.cls === 'scroll' || item.cls === 'spellbook' ? CLR_WHITE : NO_COLOR),
    };
    curseLoadstoneLeavingInventory(dropped);
    if (Array.isArray(dropped.contents)) dropped.contents = [...dropped.contents];
    if (Array.isArray(dropped.cobj)) dropped.cobj = [...dropped.cobj];
    normalizeContainedObjectParents(dropped);
    removeInventoryItem(item, item.quan || 1);
    const placed = placeObjectOnFloorWithEffects(dropped, dropped.ox, dropped.oy, messages, 'drop', {
        usedUpShopBillOnDestroy: true,
    });
    if (!placed) clearObjectShopBillState(item);
    let shopSale = null;
    if (placed && !sellobjReturnUnpaidToShop(dropped, dropped.ox, dropped.oy)) {
        shopSale = beginDroppedPaidObjectSale(dropped, dropped.ox, dropped.oy);
        if (shopSale?.message) messages.push(shopSale.message);
    }
    if (placed && !shopSale?.prompt) stackDroppedFloorObject(dropped);
    return dropped;
}

function wandZapSpendMessages(usageMessages, chargeUse) {
    const messages = [...usageMessages];
    if (chargeUse?.wrested) messages.push('You wrest one last charge from the worn-out wand.');
    return messages;
}

function dustWand(item) {
    const name = pickupObjectName(item);
    removeInventoryItem(item);
    return `The ${name} turns to dust.`;
}

function useUpDustWand(item) {
    const name = pickupObjectName(item);
    useUpInventoryItem(item, item?.quan || 1);
    return `The ${name} turns to dust.`;
}

async function beginWishPrompt({ moveCost = 0, dustItem = null, message = 'For what do you wish?' } = {}) {
    game._wish_text = '';
    game._wish_tries = 0;
    game._wish_move_cost = moveCost;
    game._wish_dust_item = dustItem;
    await setMessage(message);
    game._command_mode = 'wizardWish';
}

async function setWishResultMessage(message, more = false) {
    const moveCost = game._wish_move_cost || 0;
    const dustItem = game._wish_dust_item || null;
    game._wish_move_cost = 0;
    game._wish_dust_item = null;
    game._wish_tries = 0;
    game.context.move = moveCost;
    let text = message;
    if (dustItem && (game.inventory || []).includes(dustItem)) {
        const dustMessage = dustWand(dustItem);
        text = text ? `${text}  ${dustMessage}` : dustMessage;
    }
    await setMessage(text, more);
}
