export function monsterGrowUp(mon, victim) {
    if (!mon || (mon.mhp || 0) <= 0) return false;
    const oldData = mon.data || {};
    const oldLevel = mon.m_lev ?? oldData.hpLevel ?? oldData.mlevel ?? 0;
    const oldMaxHp = mon.mhpmax ?? mon.mhp ?? 1;
    const victimLevel = victim?.m_lev ?? victim?.data?.hpLevel ?? victim?.data?.mlevel ?? 0;
    let hpThreshold = oldLevel ? oldLevel * 8 : 4;
    let levelLimit = Math.trunc(3 * (oldData.mlevel ?? 0) / 2);
    const grownName = GROWNUP_MONSTERS.get(oldData.name);
    const grownData = grownName ? RANDOM_MONSTER_BY_NAME.get(grownName) : null;

    if (grownData && (grownData.mlevel ?? 0) > levelLimit) levelLimit = grownData.mlevel ?? levelLimit;
    let maxIncrease = rnd(victimLevel + 1);
    if (oldMaxHp + maxIncrease > hpThreshold + 1)
        maxIncrease = Math.max(hpThreshold + 1 - oldMaxHp, 0);
    const currentIncrease = maxIncrease > 1 ? rn2(maxIncrease) : 0;
    mon.mhpmax = oldMaxHp + maxIncrease;
    mon.mhp = (mon.mhp ?? 1) + currentIncrease;
    if (mon.mhpmax <= hpThreshold) return true;

    if (levelLimit < 5) levelLimit = 5;
    else if (levelLimit > 49) levelLimit = (oldData.mlevel ?? 0) > 49 ? 50 : 49;
    mon.m_lev = oldLevel + 1;
    if (grownData && mon.m_lev >= (grownData.mlevel ?? 0)) {
        mon.data = { ...grownData, hpLevel: mon.m_lev };
        newsym(mon.mx, mon.my);
        levelLimit = mon.m_lev;
    }
    if (mon.m_lev > levelLimit) {
        mon.m_lev--;
        if (mon.mhpmax === hpThreshold + 1) mon.mhpmax--;
    }
    if (mon.mhpmax > 400) mon.mhpmax = 400;
    if ((mon.mhp || 0) > mon.mhpmax) mon.mhp = mon.mhpmax;
    return true;
}

export function refreshSwallowOverlay(more = !!game._message_more) {
    const message = game._pending_message || '';
    const prompt = more && message ? `${message}--More--` : message;
    const overlay = [[0, 0, prompt]];
    if ((game.u?._statusSuffix || '').includes('Hallu')) {
        for (const [row, col, ch] of SWALLOW_OVERLAY_CELLS) {
            if (ch === '@') {
                overlay.push([row, col, ch, 0, CLR_WHITE]);
                continue;
            }
            const rawColor = DISPLAY_MONSTER_COLORS[rn2_on_display_rng(DISPLAY_MONSTER_COLORS.length)];
            const color = rawColor === CLR_BLACK || rawColor === CLR_GRAY ? NO_COLOR : rawColor;
            overlay.push([row, col, ch, 0, color]);
        }
    } else {
        overlay.push(
            [5, 25, '/⎺\\', 0, CLR_CYAN],
            [6, 25, '│', 0, CLR_CYAN],
            [6, 26, '@', 0, CLR_WHITE],
            [6, 27, '│', 0, CLR_CYAN],
            [7, 25, '\\⎽/', 0, CLR_CYAN],
        );
    }
    if (more || !message) game._swallow_overlay_lines = overlay.map(line => [...line]);
    setOverlay(overlay, 22, false, 0);
    const disp = game.nhDisplay;
    if (disp?.setCell) {
        disp.clearRow?.(0);
        for (const [row, col, text, attr = 0, color = NO_COLOR] of overlay) {
            const value = String(text);
            for (let i = 0; i < value.length; i++)
                disp.setCell(col + i, row, value[i], color, attr);
        }
        if (more && message) disp.setCursor(String(prompt).trimEnd().length, 0);
        else if (game._command_mode === 'extendedCommand') disp.setCursor(2 + String(game._extended_command || '').length, 0);
        else if (game._command_mode && message.includes('?')) disp.setCursor(String(message).trimEnd().length + 1, 0);
        else if (game.u?.ux > 0) disp.setCursor(game.u.ux - 1, game.u.uy + 1);
    }
    game._pending_message = message;
    game._message_more = more ? 1 : 0;
    game._swallow_overlay_active = 1;
}

