    const messages = [`${floorObjectSubject({ ...obj, quan: 1 })} hits the ${ceilingName}.`];
    projectileTopLevelBreakMessage(obj, breakKind, messages);
    await applyHeroThrownFragileBreakSideEffects(obj, messages);
