function normalizeWishedSpelling(name) {
    return String(name || '').replace(/armour/ig, match => match[0] === 'A' ? 'Armor' : 'armor');
}

function resolveWishedSpellingAlias(lowerName) {
    const normalized = String(lowerName || '').trim().replace(/\s+/g, ' ');
    const explicit = WISH_EXPLICIT_SPELLING_ALIASES.get(normalized);
    if (explicit) return { name: explicit, skipNamedesc: true };
    const alias = WISH_NAME_ALIASES.get(normalized);
    if (alias) return { name: alias, skipNamedesc: false };
    return { name: singularizeWishedPluralName(normalized), skipNamedesc: false };
}

function singularizeWishedPluralName(normalized) {
    for (const [name, baseObject] of WISH_BASE_OBJECTS.entries()) {
        if (String(baseObject?.plural || '').toLowerCase() === normalized) return name;
    }
    for (const [plural, singular] of [
        [/^wands of (.+)$/, 'wand of $1'],
        [/^rings of (.+)$/, 'ring of $1'],
        [/^potions of (.+)$/, 'potion of $1'],
        [/^spellbooks of (.+)$/, 'spellbook of $1'],
        [/^scrolls of (.+)$/, 'scroll of $1'],
    ]) {
        const match = normalized.match(plural);
        if (match) return singular.replace('$1', match[1]);
    }
    return normalized;
}

function makeWishedGrayStoneObject(lowerName) {
    if (lowerName !== 'gray stone' && lowerName !== 'grey stone') return null;
    const roll = rnd(38);
    const name = roll <= 10 ? 'luckstone'
        : roll <= 20 ? 'loadstone'
            : roll <= 28 ? 'touchstone'
                : 'flint';
    const baseObject = WISH_BASE_OBJECTS.get(name);
    const otmp = mksobj(baseObject.otyp, true, false);
    return Object.assign(otmp, baseObject, {
        kind: 'gray stone',
        actualKind: name,
        gemDescription: 'gray stone',
        _display_color: CLR_GRAY,
        wishedfor: true,
    });
}

