            const alignment = piety ? `${piety} ${align}` : align;
            await setMessage(`Status of ${game.plname || 'you'} (${alignment}):  Level ${game.u?.ulevel || 1}  HP ${game.u?.uhp || 0}(${game.u?.uhpmax || 0})  AC ${game.u?.uac ?? 10}.`);
            if (usedThisTurn) game.context.move = 1;
