        const abcLargeBox = !!(largeBox && game.flags?.lootabc);
        const takeoutKey = abcLargeBox ? 'a' : 'o';
        const putinKey = abcLargeBox ? 'b' : 'i';
        const bothKey = abcLargeBox ? 'c' : 'b';
        const reversedKey = abcLargeBox ? 'd' : 'r';
